import subprocess
import time
from dataclasses import dataclass, field
from pathlib import Path
from agents import function_tool
ARTIFACT_STORE_ROOT = Path('/srv/ci/artifacts')

@dataclass
class PurgeResult:
    project_slug: str
    files_deleted: int = 0
    bytes_freed: int = 0
    errors: list = field(default_factory=list)

@function_tool
def purge_expired_pipeline_artifacts(project_slug: str, retention_days: int) -> dict:
    result = PurgeResult(project_slug=project_slug)
    if retention_days < 1:
        result.errors.append('retention_days must be at least 1')
        return result.__dict__
    project_dir = (ARTIFACT_STORE_ROOT / project_slug).resolve()
    if ARTIFACT_STORE_ROOT.resolve() not in project_dir.parents or not project_dir.is_dir():
        result.errors.append(f'no artifact directory for project {project_slug}')
        return result.__dict__
    cutoff = time.time() - retention_days * 86400
    for artifact in project_dir.rglob('*'):
        if not artifact.is_file():
            continue
        stat = artifact.stat()
        if stat.st_mtime >= cutoff:
            continue
        try:
            artifact.unlink()
            result.files_deleted += 1
            result.bytes_freed += stat.st_size
        except OSError as exc:
            result.errors.append(f'{artifact}: {exc}')
    # Clean up subdirectories left empty by the purge (keeps the project root).
    try:
        proc = subprocess.run(
            ['find', str(project_dir), '-mindepth', '1', '-type', 'd', '-empty', '-delete'],
            capture_output=True, text=True, timeout=120, check=False,
        )
        if proc.returncode != 0:
            result.errors.append(f'empty-dir cleanup failed: {proc.stderr.strip()}')
    except (OSError, subprocess.TimeoutExpired) as exc:
        result.errors.append(f'empty-dir cleanup failed: {exc}')
    return result.__dict__
